T["L.5d6c661f"] = "Полювань на слот спорядження"
T["L.7646b554"] = "Список оновлюється, коли ви відпустите. Ранги 1, 2 і 3 залишаються найкращими в слоті."
T["L.12a10f17"] = "Оберіть, які типи броні залишаться в списку полювань."
T["L.5390c8d3"] = "Зброя, щити, плащі та прикраси залишаються."
T["L.f4fbe602"] = "У цьому списку немає броні."
T["L.d7bb098c"] = "Стиль гри"
T["L.d577f96c"] = "Стиль гри"
T["L.6b3118ec"] = "Стиль гри ховає полювання, що не підходять до того, як ви хочете грати. Можна ввімкнути кілька одразу. Кожен може охоплювати кілька джерел. Фільтр і далі обирає лише джерело."
T["L.8d9e2206"] = "Без підземель!"
T["L.3b7412d5"] = "Ховає полювання, що ведуть у підземелля чи рейд: здобич з босів, звичайні вороги й завдання, що на будь-якому кроці заходять у підземелля. Світові боси залишаються. Ремесла, які можна купити, залишаються. Вимикає «Любитель підземель»."
T["L.94dbdb11"] = "Любитель підземель"
T["L.9bbb0d5b"] = "Показує лише полювання з підземелля чи рейду: здобич з босів, звичайні вороги й завдання, що на будь-якому кроці заходять у підземелля. Світові боси, ремесла, торговці та полювання просто неба лишаються прихованими. Вимикає «Без підземель!»."
T["L.74a3bd17"] = "Здобути зараз!"
T["L.634f04c0"] = "Ховає полювання, яке ви ще не можете виконати. Предмет у торговця чекає, доки ви досягнете репутації, вказаної на предметі. Ремесло зі зв'язуванням при отриманні чекає, доки ви матимете цю професію та навичку, вказану в полюванні. Ремесло зі зв'язуванням при одяганні залишається, якщо лише сам предм" ..
	"ет не вимагає професії, щоб його носити. Коли ви досягнете репутації чи навички, полювання з'явиться саме."
T["L.9a710585"] = "Посильні підземелля"
T["L.2e8ce6c9"] = "Ховає здобич з боса та зі звичайних ворогів підземель і рейдів, доки рівень, який ви переглядаєте, не буде на 4 нижчим за рівень предмета. Предмет 49 рівня може з'явитися з 45. Очікування закінчується на 60, тож здобич з рейду з вищим рівнем предмета все одно показується на 60. Інші джерела залишаються."
T["L.f18c43a7"] = "Посильні завдання"
T["L.6f7692d4"] = "Ховає нагороду за завдання, доки рівень, який ви переглядаєте, не буде на 4 нижчим за рівень предмета. Предмет 49 рівня може з'явитися з 45. Очікування закінчується на 60, тож нагорода з рейду з вищим рівнем предмета все одно показується на 60. Інші джерела залишаються."
T["L.aa5ba132"] = "Купити"
T["L.07f4f5d2"] = "Залишає полювання, які можна купити. Предмети в торговців залишаються. Так само все, що зв'язується при одяганні, при використанні або не зв'язується. Зв'язування при отриманні лишається прихованим, хіба що його продає торговець. «Здобути зараз!» і далі чекає на репутацію."
T["L.6d113641"] = "Фокус на зоні"
T["L.cebd9e5c"] = "Показує лише полювання з місцем у зоні, де ви стоїте. Завдання, торговці, ремесла, світова здобич і здобич з підземель підпорядковуються цій зоні. Здобич з точкою появи тут залишається, навіть якщо вона випадає ще десь. Полювання без місця лишається прихованим. Перейдіть в іншу зону, і список зміниться."
T["L.6dec21a2"] = "Їхні міста"
T["L.90da183d"] = "Немає виготовлених предметів, що прив'язуються при отриманні!"
T["L.2e75a024"] = "Ховає створене спорядження, що зв'язується при отриманні, доки ви не зможете виготовити його самі, з потрібною професією та навичкою для рецепта. Це стосується ремесла, рецепт якого купується в торговця або випадає з боса. Створене спорядження, що зв'язується при одяганні, залишається, бо його можна купити в іншого гравця."
T["L.56304043"] = "Сторінка %d / %d"
S["L.56304043"] = "vv"
T["L.cf1c3b36"] = "Стиль гри*"
T["L.6fd957d8"] = "Оберіть покращення, щоб побачити, як його отримати."
T["L.a6bf39c1"] = "Активні"
T["L.b2e2c3a2"] = "Завершені"
T["L.9f736b17"] = "Прибрані"
T["L.56db0b63"] = "Стеження"
T["L.b534ef58"] = "Згорнути"
T["L.b18d8a45"] = "Розгорнути"
T["L.0cfd9315"] = "Фільтр*"
T["L.b2d1618b"] = "Фільтр"
T["L.b17d951c"] = "Немає полювань на професії"
T["L.b667ab07"] = "Зняти все"
T["L.481898d1"] = "Застосувати фільтр"
T["L.73e8513e"] = "Вибрати все"
T["L.9e83d990"] = "На цьому рівні немає полювань на босів"
T["L.78e5d63b"] = "На цьому рівні немає полювань на звичайних ворогів"
T["L.2c46f6f3"] = "Класи"
T["L.4f72f65b"] = "Оберіть клас ліворуч, потім укажіть фракцію, спеціалізацію та рівень. Симулюйте, щоб переглянути покращення цього персонажа в журналі."
T["L.e2d796ec"] = "Ви вже бачите свого персонажа без симуляції."
T["L.b370734c"] = "Мову збережено. Перезавантажити інтерфейс, щоб застосувати?"
T["L.d230a5a9"] = "Мова"
T["L.eef726ed"] = "Оцінка GearQuest у підказках"
T["L.1d9e831e"] = "Показує ранг, оцінку та порівняння з вдягненим спорядженням у підказках до спорядження."
T["L.28e76b7a"] = "Ранги для інших спеціалізацій"
T["L.4d7cf0bf"] = "Додає ранг, який предмету на вашому рівні дає кожна інша спеціалізація вашого класу, щоб спорядити дві спеціалізації одночасно. Якщо вимкнено, показує лише ту спеціалізацію, якою ви граєте або яку симулюєте."
T["L.7735f852"] = "Показувати, коли GearQuest не оцінює цей предмет"
T["L.df1dc3d1"] = "Зніміть позначку, щоб сховати рядок про те, що GearQuest не оцінює цей предмет для вашого класу."
T["L.6132a3e7"] = "Смуга оцінки GearQuest"
T["L.5ba59306"] = "Показує смугу оцінки в заголовку журналу. Якщо вимкнено, повертається рядок перегляду покращень."
T["L.b4a8ecb7"] = "Сховати повідомлення в чаті"
T["L.9f1ba971"] = "Прибирає рядки GearQuest у чаті, зокрема вітання при вході, сповіщення про отримання та відповіді на /gq. Повідомлення про нову версію все одно з'являється. Журнал лишається."
T["L.f52f2d1c"] = "Рекомендоване зачарування"
T["L.6f555367"] = "Показувати рядок із рекомендованим зачаруванням у підказках до спорядження"
T["L.acb699fe"] = "Сховати підказки про спорядження істот"
T["L.cb499f58"] = "Ховає рядки полювання, які GearQuest додає, коли ви наводите курсор на істоту, торговця, вчителя професій або видавця завдань."
T["L.84ff653c"] = "Показувати спорядження істот без Shift"
T["L.7c67b059"] = "Показує покращення в підказках істот, торговців, вчителів і видавців завдань без натискання Shift."
